# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

OPEN = parse_span("09:00-17:00")

def run(*texts):
    return find_gaps([parse_span(t) for t in texts], OPEN)

class GapTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        self.assertEqual(
            run("09:00-12:00", "13:00-17:00"),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_edges_and_overlaps(self):
        self.assertEqual(
            run("10:00-12:00", "11:00-13:00"),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 13:00-17:00 (240 min)"
            ]
        )

    def test_nobody_worked(self):
        self.assertEqual(
            run(), ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_cover(self):
        self.assertEqual(run("09:00-17:00"), [])

    def test_outside_opening_hours(self):
        with self.assertRaises(ValueError):
            run("08:00-12:00")

if __name__ == "__main__":
    unittest.main()
